{
  "schemaVersion": "authorization-local-edit/v1",
  "reason": "Update the accepted space-member removal policy to the changed brief and revise both policy-linked scenario expectations while preserving the unchanged source, identities, relations, premises, task ID, and all other assessment fields.",
  "operations": [
    {
      "op": "replace",
      "path": "/assessment/policies/accepted-policy/text",
      "value": "An active space member may delete their own membership and may remove a different active member of the same space without space administrator authority."
    },
    {
      "op": "replace",
      "path": "/assessment/policies/accepted-policy/location",
      "value": "author-briefs.json#/memos-space-policy/changedPolicy"
    },
    {
      "op": "replace",
      "path": "/assessment/policies/accepted-policy/revision",
      "value": "changed-v1"
    },
    {
      "op": "replace",
      "path": "/assessment/scenarios/self-leave/expectation",
      "value": "allow"
    },
    {
      "op": "replace",
      "path": "/assessment/scenarios/other-member/expectation",
      "value": "allow"
    }
  ]
}

